using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<WeatherTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Gets the current weather for a city.")]
    public static string GetWeather(string city) =>
        $"The weather in {city} is 72°F and sunny.";
}

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the current application configuration.")]
    public static string GetAppSettings() =>
        """
        {
          "theme": "dark",
          "language": "en-US",
          "maxRetries": 3,
          "timeoutSeconds": 30
        }
        """;
}

